import { expect, test } from 'claude-code/testing'

import { candidatePathsOfClass, composerAutoloadPath, composerRootOf, parseComposerClassMap, parseComposerNamespacePrefixes } from './composer'

const NAMESPACE_TABLE = `<?php

// autoload_psr4.php @generated by Composer

$vendorDir = dirname(__DIR__);
$baseDir = dirname($vendorDir);

return array(
    'Symfony\\\\Component\\\\Mailer\\\\' => array($vendorDir . '/symfony/mailer'),
    'Doctrine\\\\ORM\\\\' => array($vendorDir . '/doctrine/orm/src'),
    'Doctrine\\\\' => array($vendorDir . '/doctrine/common/src', $vendorDir . '/doctrine/legacy/lib'),
    'Shop\\\\Tests\\\\' => array($baseDir . '/tests'),
    'Shop\\\\' => array($baseDir . '/src'),
    'Root\\\\' => array($baseDir),
);
`

test('the Composer root of a file is its nearest ancestor holding a composer.json', async () => {
  const files = ['server/composer.json', 'server/src/Order.php', 'server/tools/linter/composer.json', 'server/tools/linter/src/Rule.php', 'storefront/package.json']
  expect(composerRootOf('server/src/Order.php', files)).toBe('server')
  expect(composerRootOf('server/tools/linter/src/Rule.php', files)).toBe('server/tools/linter')
  expect(composerRootOf('server/vendor/doctrine/orm/src/EntityRepository.php', files)).toBe('server')
  expect(composerRootOf('storefront/src/main.php', files)).toBe(null)
  expect(composerRootOf('src/Order.php', ['composer.json', 'src/Order.php'])).toBe('')
})

test('the namespace table is read with its directories under the root, the longest prefixes first', async () => {
  const prefixes = parseComposerNamespacePrefixes(NAMESPACE_TABLE, 'server')
  expect(prefixes.map(entry => entry.prefix)).toEqual(['Symfony\\Component\\Mailer\\', 'Doctrine\\ORM\\', 'Shop\\Tests\\', 'Doctrine\\', 'Shop\\', 'Root\\'])
  expect(prefixes.find(entry => entry.prefix === 'Doctrine\\')?.directories).toEqual(['server/vendor/doctrine/common/src', 'server/vendor/doctrine/legacy/lib'])
  expect(prefixes.find(entry => entry.prefix === 'Shop\\')?.directories).toEqual(['server/src'])
  expect(prefixes.find(entry => entry.prefix === 'Root\\')?.directories).toEqual(['server'])
})

test('a class is looked for under every prefix that fits, the most specific first, in each of its directories', async () => {
  const prefixes = parseComposerNamespacePrefixes(NAMESPACE_TABLE, '')
  expect(candidatePathsOfClass(prefixes, 'Doctrine\\ORM\\EntityRepository')).toEqual([
    'vendor/doctrine/orm/src/EntityRepository.php',
    'vendor/doctrine/common/src/ORM/EntityRepository.php',
    'vendor/doctrine/legacy/lib/ORM/EntityRepository.php',
  ])
  expect(candidatePathsOfClass(prefixes, 'Shop\\Entity\\Order')).toEqual(['src/Entity/Order.php'])
  expect(candidatePathsOfClass(prefixes, 'Shop\\Tests\\OrderTest')).toEqual(['tests/OrderTest.php', 'src/Tests/OrderTest.php'])
  expect(candidatePathsOfClass(prefixes, 'Unknown\\Thing')).toEqual([])
})

test('the class map gives the file of a class no prefix covers', async () => {
  const classMap = parseComposerClassMap(
    "<?php\n$vendorDir = dirname(__DIR__);\n$baseDir = dirname($vendorDir);\nreturn array(\n    'Composer\\\\InstalledVersions' => $vendorDir . '/composer/InstalledVersions.php',\n    'Legacy_Mailer' => $vendorDir . '/legacy/mailer/Mailer.php',\n    'Kernel' => $baseDir . '/app/Kernel.php',\n);\n",
    'server',
  )
  expect(Object.fromEntries(classMap)).toEqual({
    'Composer\\InstalledVersions': 'server/vendor/composer/InstalledVersions.php',
    Legacy_Mailer: 'server/vendor/legacy/mailer/Mailer.php',
    Kernel: 'server/app/Kernel.php',
  })
})

test('the tables are read under the vendor folder of the root', async () => {
  expect(composerAutoloadPath('server', 'autoload_psr4.php')).toBe('server/vendor/composer/autoload_psr4.php')
  expect(composerAutoloadPath('', 'autoload_classmap.php')).toBe('vendor/composer/autoload_classmap.php')
})
